// Grist envoie un tableau d'enregistrements (les lignes ajoutées dans PM_Notifications).
// On gère les deux formats possibles (tableau direct ou sous .body) et on sort 1 item / notification.
const input = $input.first().json;
let rows = input.body !== undefined ? input.body : input;
if (!Array.isArray(rows)) rows = [rows];
return rows.map(r => ({ json: r }));
